import{_ as t,o as a,c as i,a as n}from"./app.DLiRGumz.js";const p=JSON.parse('{"title":"Agent Identity & Sovereignty Depth (WP-6004)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/AGENT_IDENTITY_SOVEREIGNTY_DEPTH.md","filePath":"reference/AGENT_IDENTITY_SOVEREIGNTY_DEPTH.md","lastUpdated":1771753292000}'),r={name:"reference/AGENT_IDENTITY_SOVEREIGNTY_DEPTH.md"};function o(s,e,l,d,c,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-identity-sovereignty-depth-wp-6004" tabindex="-1">Agent Identity &amp; Sovereignty Depth (WP-6004) <a class="header-anchor" href="#agent-identity-sovereignty-depth-wp-6004" aria-label="Permalink to &quot;Agent Identity &amp; Sovereignty Depth (WP-6004)&quot;">​</a></h1><p>This document defines the depth for <strong>Agent Identity</strong>, enabling verifiable provenance and cross-platform sovereignty for <code>thegent</code> droids.</p><h2 id="_1-decentralized-identifier-did-for-agents" tabindex="-1">1. Decentralized Identifier (DID) for Agents <a class="header-anchor" href="#_1-decentralized-identifier-did-for-agents" aria-label="Permalink to &quot;1. Decentralized Identifier (DID) for Agents&quot;">​</a></h2><p>Every agent instance in <code>thegent</code> is assigned a <strong>W3C-compliant Decentralized Identifier (DID)</strong>.</p><ul><li><strong>DID Format</strong>: <code>did:thegent:swarm-1:agent-alpha-42</code></li><li><strong>DID Document</strong>: A JSON metadata file that defines the agent&#39;s public keys, capabilities, and service endpoints.</li></ul><h2 id="_2-verifiable-credentials-vc" tabindex="-1">2. Verifiable Credentials (VC) <a class="header-anchor" href="#_2-verifiable-credentials-vc" aria-label="Permalink to &quot;2. Verifiable Credentials (VC)&quot;">​</a></h2><p>Agents carry <strong>Verifiable Credentials</strong> issued by the project owner or the policy engine:</p><ul><li><strong>Capability VC</strong>: Proof that an agent is authorized to use specific tools (e.g., <code>git-push</code>, <code>mcp-exec</code>).</li><li><strong>Identity VC</strong>: Proof that the agent belongs to a specific swarm and has been verified by a previous quality gate.</li></ul><h2 id="_3-agent-specific-signing-keys" tabindex="-1">3. Agent-Specific Signing Keys <a class="header-anchor" href="#_3-agent-specific-signing-keys" aria-label="Permalink to &quot;3. Agent-Specific Signing Keys&quot;">​</a></h2><p>To support the <strong>MAIF artifact specification</strong>, each agent maintains its own cryptographic key pair:</p><ul><li><strong>Private Key</strong>: Stored in the agent&#39;s secure local state (L2 memory).</li><li><strong>Public Key</strong>: Published in its DID Document.</li><li><strong>Usage</strong>: Every action result and audit event is signed by the agent&#39;s key, providing non-repudiable proof of agency.</li></ul><h2 id="_4-cross-platform-sovereignty" tabindex="-1">4. Cross-Platform Sovereignty <a class="header-anchor" href="#_4-cross-platform-sovereignty" aria-label="Permalink to &quot;4. Cross-Platform Sovereignty&quot;">​</a></h2><p>When an agent &quot;migrates&quot; between platforms (e.g., from Cursor to Claude Code):</p><ol><li><strong>Context Export</strong>: The agent exports its <code>Identity_VC</code> and recent <code>Continuity_Packet</code>.</li><li><strong>Context Import</strong>: The target platform verifies the VC against the global <code>thegent</code> registry.</li><li><strong>Resumption</strong>: The agent resumes its run with its existing identity and signature chain intact.</li></ol><hr><p><em>Cross-ref: <a href="./MAIF_ARTIFACT_SPEC_DEPTH.html">MAIF_ARTIFACT_SPEC_DEPTH.md</a> | <a href="./../plans/MULTI_PLATFORM_PARITY_MASTER_PLAN.html">MULTI_PLATFORM_PARITY_MASTER_PLAN.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',28)])])}const f=t(r,[["render",o]]);export{p as __pageData,f as default};
